import {VERSION,PROFILE,ROLES,COLORS,DEMO,f,validateMML,writeMidi,readMidi,compareMidi,writeABC,readABC,sha256,secondsAt,beatAtSeconds} from './core.js';
import {Player} from './player.js';

const $=id=>document.getElementById(id),programs=[0,0,0,0,0,0];
let result=null,midi=null,abc='',hashes=null,dirty=true,busy=false,editVersion=0,title='內建示範',sourceFile=null,sourceUrl=null,sourceHash=null,sourceMode=false,lastValidation=null,toastTimer=null;
const player=new Player({onState:()=>{refreshTransport();refreshSnapshot()}});
const source=$('source-audio');
const time=s=>{if(!Number.isFinite(s))return '—';s=Math.max(0,s);return `${Math.floor(s/60)}:${(s%60).toFixed(2).padStart(5,'0')}`};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toast=message=>{$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500)};
const settings=()=>({title,meterText:$('meter-map').value,pickup:$('pickup').value.trim(),finalPartial:$('final-partial').value.trim(),drumText:$('drum-profile').value,programs:[...programs]});
function currentSeconds(){return sourceMode?Math.max(0,source.currentTime-Number($('audio-offset').value||0)):player.position}
function enableExports(enabled){for(const id of ['export-mml','export-midi','export-abc','export-report','export-project'])$(id).disabled=!enabled}
function markDirty(){editVersion++;dirty=true;player.pause();source.pause();sourceMode=false;$('validation-badge').textContent='內容已變更';$('validation-badge').className='badge pending';$('editor-status').textContent='變更尚未檢查，請重新載入。';enableExports(false);$('play').disabled=true;$('seek').disabled=true;$('switch-audio').disabled=true;$('snapshot-badge').className='badge pending';$('snapshot-badge').textContent='回讀已過期';$('snapshot-summary').textContent='內容或設定已變更，舊回讀不能驗證新版本。';$('gates').innerHTML=gate('目前版本','PENDING','內容已變更，請重新檢查')+gate('原曲分層 A/B','PENDING','需逐段聽驗')+gate('Mobile 實機','PENDING','需遊戲試奏');refreshTransport()}
function gate(label,status,detail){const cls=status==='PASS'?'pass':status==='FAIL'?'fail':'pending';return `<div class="gate"><span>${esc(label)}<small>${esc(detail)}</small></span><span class="badge ${cls}">${status}</span></div>`}
async function validate(){if(busy)return;busy=true;const requestVersion=editVersion;$('validate').disabled=true;player.pause();source.pause();sourceMode=false;
  try{const r=validateMML($('mml').value,settings());result=r;lastValidation=new Date().toISOString();$('issues').replaceChildren();
    $('validation-badge').textContent=r.ok?'技術檢查通過':'需要修正';$('validation-badge').className='badge '+(r.ok?'pass':'fail');
    const errors=r.errors.map(e=>`<div class="issue">${e.role?esc(e.role)+' · ':''}${e.position?'第'+e.position+'字 · ':''}${esc(e.message)}</div>`).join('');
    const warningHtml=r.warnings.map(w=>`<div class="issue warning">${esc(w)}</div>`).join('');$('issues').innerHTML=errors+warningHtml;
    if(!r.ok){dirty=true;enableExports(false);$('play').disabled=true;$('stop').disabled=true;$('seek').disabled=true;$('switch-audio').disabled=true;$('gates').innerHTML=gate('Strict Mobile／時間線','FAIL','請先處理上方錯誤')+gate('播放器回讀','PENDING','此版本未載入')+gate('原曲／Mobile','PENDING','未完成');$('snapshot-badge').textContent='此版本未載入';$('snapshot-badge').className='badge pending';$('snapshot-summary').textContent='修正後重新檢查，才會更新回讀。';renderMetrics();return}
    midi=writeMidi(r.song);const actual=readMidi(midi),match=compareMidi(r.song,actual);if(!match.ok)throw Error(match.errors.join('；'));
    abc=writeABC(r.song);const abcCheck=compareMidi(r.song,readABC(abc,settings()));if(!abcCheck.ok)throw Error('ABC回解不一致：'+abcCheck.errors.join('；'));const raw=$('mml').value.trim();hashes={mml:await sha256(raw),midi:await sha256(midi),abc:await sha256(abc),settings:await sha256(JSON.stringify(settings()))};
    if(requestVersion!==editVersion){markDirty();toast('內容在檢查中變更，請再次載入');return}
    await player.load(midi);const loaded=compareMidi(r.song,player.capture().effectiveModel);if(!loaded.ok)throw Error('播放器回讀不同：'+loaded.errors.join('；'));
    if(requestVersion!==editVersion){markDirty();return}dirty=false;$('song-title').textContent=title;$('song-description').textContent=title==='內建示範'?'原創測試片段 · 包含中途變拍與速度切換':'以目前 MML 與預覽設定為準';$('editor-status').textContent='原文保留 · 請匯出檔案保存';$('play').disabled=false;$('stop').disabled=false;$('seek').disabled=false;$('switch-audio').disabled=!sourceFile;$('loop-end').value=r.song.total.includes('/')?f(r.song.total).num():r.song.total;
    player.setMix({layer:Number($('layer').value),muted:new Set(),solo:null});$('loop-enabled').checked=false;player.setLoop(0,0,false);enableExports(true);renderMetrics();renderTracks();refreshGates();refreshSnapshot();refreshTransport();drawRoll();checkAudioTiming();
  }catch(e){dirty=true;enableExports(false);$('play').disabled=true;$('seek').disabled=true;$('switch-audio').disabled=true;$('validation-badge').textContent='載入失敗';$('validation-badge').className='badge fail';$('issues').innerHTML+=`<div class="issue">${esc(e.message)}</div>`;toast(e.message)}finally{busy=false;$('validate').disabled=false}
}
function renderMetrics(){const song=result?.song;const notes=song?.tracks.reduce((a,t)=>a+t.events.length,0)||0;$('metrics').innerHTML=[['音符事件',notes],['總拍數',song?.total||'—'],['實際小節',song?.bars.length||'—']].map(([label,value])=>`<div class="metric"><strong>${esc(value)}</strong><span>${label}</span></div>`).join('')}
function refreshGates(){if(dirty||!result?.ok)return;const match=compareMidi(result.song,player.capture().effectiveModel);$('gates').innerHTML=gate('Strict Mobile／事件','PASS','六軌字數、語法、Tempo與總拍長')+gate('MIDI／已載入引擎',match.ok?'PASS':'FAIL',match.ok?'音符、音尾、力度、音量、Program及拍號一致':match.errors.join('；'))+gate('原曲分層 A/B','PENDING',sourceFile?'音檔已加入；身份、有效區間及聽驗待確認':'尚未加入原曲音檔')+gate('Mobile 實機','PENDING','工作台合成音色不等於遊戲音色')}
function renderTracks(){if(!result?.ok)return;const options=[[0,'鋼琴近似'],[24,'吉他近似'],[32,'低音近似'],[40,'弦樂近似'],[80,'柔和合成']];$('tracks').innerHTML=result.song.tracks.map((t,i)=>`<div class="track" style="--track-color:${COLORS[i]}"><div class="track-name"><span>${t.role}</span><span>${t.characters}/2400</span></div><div class="track-meta">${t.events.length}音 · ${result.song.drums?.role===t.role?'鼓面預覽':t.events.length?Math.min(...t.events.map(e=>e.pitch))+'–'+Math.max(...t.events.map(e=>e.pitch)):'空軌保留'}</div><div class="track-actions"><button data-solo="${i}" aria-label="單聽${t.role}">Solo</button><button data-mute="${i}" aria-label="靜音${t.role}">Mute</button></div><select data-program="${i}" aria-label="${t.role}预覽音色" ${result.song.drums?.role===t.role?'disabled':''}>${options.map(([n,label])=>`<option value="${n}" ${programs[i]===n?'selected':''}>${label}</option>`).join('')}${options.some(([n])=>n===programs[i])?'':`<option selected value="${programs[i]}">Program ${programs[i]}</option>`}</select></div>`).join('');
  for(const b of $('tracks').querySelectorAll('[data-solo]'))b.addEventListener('click',()=>{if(dirty)return;const i=Number(b.dataset.solo);player.setMix({solo:player.solo===i?null:i});syncMixButtons();drawRoll()});
  for(const b of $('tracks').querySelectorAll('[data-mute]'))b.addEventListener('click',()=>{if(dirty)return;const i=Number(b.dataset.mute),muted=new Set(player.muted);muted.has(i)?muted.delete(i):muted.add(i);player.setMix({muted});syncMixButtons();drawRoll()});
  for(const sel of $('tracks').querySelectorAll('[data-program]'))sel.addEventListener('change',()=>{programs[Number(sel.dataset.program)]=Number(sel.value);markDirty()});
  const s=result.song;$('map-summary').textContent='Tempo '+s.tempo.map(x=>`${x.beat}拍 T${x.bpm}`).join(' → ')+'　｜　拍號 '+s.meter.map(x=>`${x.beat}拍 ${x.numerator}/${x.denominator}`).join(' → ');syncMixButtons();
}
function syncMixButtons(){for(const b of $('tracks').querySelectorAll('[data-solo]')){const active=Number(b.dataset.solo)===player.solo;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))}for(const b of $('tracks').querySelectorAll('[data-mute]')){const active=player.muted.has(Number(b.dataset.mute));b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))}}
function refreshSnapshot(){if(dirty)return;const c=player.capture();if(!c)return;const check=compareMidi(result.song,c.effectiveModel);$('snapshot-badge').textContent=check.ok?'已回讀':'回讀不符';$('snapshot-badge').className='badge '+(check.ok?'pass':'fail');$('snapshot-summary').textContent=`7軌 · ${c.effectiveModel.tracks.reduce((n,t)=>n+t.events.length,0)}音 · ${time(c.transport.durationSeconds)}。${c.transport.audioContextState==='not_started'?'音訊尚未啟動。':`音訊狀態：${c.transport.audioContextState}。`}回讀範圍為載入引擎與排程，未宣稱喇叭或遊戲已驗收。`}
function refreshTransport(){const current=currentSeconds();$('play-time').textContent=time(current);$('total-time').textContent='／ '+time(player.duration);$('play').textContent=(sourceMode?!source.paused:player.playing)?'Ⅱ 暫停':'▶ 播放';$('seek').value=player.duration?Math.min(1000,current/player.duration*1000):0;$('engine-label').textContent=dirty?'尚未載入目前版本':sourceMode?'原曲 · A':player.error||'MML 預覽 · B';$('switch-audio').textContent=sourceMode?'切到 MML':'切到原曲'}
function drawRoll(){const canvas=$('piano-roll'),width=canvas.clientWidth||800,height=230,scale=globalThis.devicePixelRatio||1;canvas.width=Math.floor(width*scale);canvas.height=height*scale;const ctx=canvas.getContext('2d');ctx.scale(scale,scale);ctx.clearRect(0,0,width,height);if(!result?.ok)return;const song=result.song,total=f(song.total).num(),notes=song.tracks.flatMap(t=>t.events);if(!notes.length)return;const low=Math.min(...notes.map(e=>e.pitch))-2,high=Math.max(...notes.map(e=>e.pitch))+2,left=36,w=width-left-10,h=height-34,y=p=>height-16-(p-low)/(high-low)*h;
  ctx.font='11px ui-monospace,monospace';ctx.fillStyle='#7e91ab';ctx.strokeStyle='#23324a';for(let p=Math.ceil(low/12)*12;p<=high;p+=12){ctx.beginPath();ctx.moveTo(left,y(p));ctx.lineTo(width,y(p));ctx.stroke();ctx.fillText('C'+(p/12-1),3,y(p)+4)}
  const skip=Math.max(1,Math.ceil(song.bars.length/(width/65)));for(let i=0;i<song.bars.length;i++){if(i%skip)continue;const bar=song.bars[i],x=left+f(bar.start).num()/total*w;ctx.strokeStyle='#24314a';ctx.beginPath();ctx.moveTo(x,20);ctx.lineTo(x,height);ctx.stroke();ctx.fillStyle='#91a2b9';ctx.fillText(String(bar.index),x+3,13)}
  song.tracks.forEach((t,i)=>{ctx.fillStyle=COLORS[i];ctx.globalAlpha=player.activeTrack(i)?.82:.16;for(const e of t.events){const x=left+f(e.start).num()/total*w,end=left+f(e.end).num()/total*w;ctx.fillRect(x,y(e.pitch)-3,Math.max(1,end-x-1),5)}});ctx.globalAlpha=1;const beat=beatAtSeconds(String(Math.max(0,currentSeconds())),player.tempo,song.total),px=left+beat/total*w;ctx.strokeStyle='#edf8f4';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(px,18);ctx.lineTo(px,height);ctx.stroke();
}
function audioTiming(){if(!sourceFile||!result?.ok)return {status:'PENDING',reason:'缺少原曲或有效候選'};const offset=Number($('audio-offset').value),endText=$('audio-end').value;if(!endText)return {status:'PENDING',reason:'尚未確認原曲有效終點'};const end=Number(endText);if(!Number.isFinite(offset)||!Number.isFinite(end)||offset<0||end<=offset||!Number.isFinite(source.duration)||end>source.duration+.001)return {status:'FAIL',reason:'有效區間需在已載入音檔範圍內，且終點大於起點'};const effective=end-offset,theoretical=secondsAt(result.song.total,result.song.tempo),loaded=player.duration,error=Math.abs(effective-theoretical)/theoretical,loadedError=Math.abs(effective-loaded)/loaded;return {status:Math.max(error,loadedError)>.02?'FAIL':'PASS',scope:'manual_interval_duration_only_not_listening',offsetSeconds:offset,endSeconds:end,effectiveSeconds:effective,mmlSeconds:theoretical,loadedModelSeconds:loaded,relativeDeviation:Math.max(error,loadedError)}}
function checkAudioTiming(){const t=audioTiming();$('audio-timing').textContent=t.relativeDeviation!==undefined?`${t.status} · 有效時長${time(t.effectiveSeconds)}，與MML／載入引擎最大偏差${(t.relativeDeviation*100).toFixed(3)}%。這只檢查你填寫的區間長度。`:t.reason+'；不自動裁尾或补拍。';refreshGates()}
function download(data,type,name){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
const filename=()=>title.replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').slice(0,70)||'MML';
async function report(){const snapshot=player.capture(),comparison=compareMidi(result.song,snapshot.effectiveModel);return {schemaVersion:1,tool:'MML Workbench',toolVersion:VERSION,profile:PROFILE,createdAt:new Date().toISOString(),validatedAt:lastValidation,title,candidateHashes:hashes,gates:{strictMobile:{status:'PASS'},midiContent:{status:'PASS'},loadedEngine:{status:comparison.ok?'PASS':'FAIL',errors:comparison.errors},sourceDuration:audioTiming(),originalListening:{status:'PENDING'},gameAcceptance:{status:'PENDING'}},source:sourceFile?{filename:sourceFile.name,sha256:sourceHash,containerSeconds:Number.isFinite(source.duration)?source.duration:null,identity:'PENDING',listening:'PENDING'}:null,settings:settings(),canonicalSong:result.song,readback:snapshot,scope:'This report certifies only named technical checks; it is not Midify readback or a Final musical/game acceptance.'}}
async function switchAudio(){if(dirty||!sourceFile)return;const pos=currentSeconds(),wasPlaying=sourceMode?!source.paused:player.playing;try{if(sourceMode){source.pause();sourceMode=false;await player.seek(pos);if(wasPlaying)await player.play()}else{const target=pos+Number($('audio-offset').value||0);if(!Number.isFinite(target)||target<0||target>=source.duration)throw Error('此位置不在原曲音檔範圍內，請核對對齊秒數');player.pause();source.currentTime=target;sourceMode=true;if(wasPlaying)await source.play()}refreshTransport();drawRoll()}catch(e){toast(e.message)}}

$('mml').value=DEMO;
$('validate').addEventListener('click',validate);
for(const id of ['mml','meter-map','pickup','final-partial','drum-profile'])$(id).addEventListener('input',()=>{if(id==='mml'&&title==='內建示範'){title='未命名樂譜';$('meter-map').value='0 4/4';$('pickup').value='';$('final-partial').value='';$('drum-profile').value='';programs.fill(0)}markDirty()});
$('demo').addEventListener('click',()=>{player.stop();source.pause();$('mml').value=DEMO;$('meter-map').value='0 4/4\n8 2/4\n10 4/4';$('pickup').value='';$('final-partial').value='';$('drum-profile').value='';programs.fill(0);title='內建示範';markDirty();void validate()});
$('mml-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>120000)throw Error('MML檔案過大');$('mml').value=(await file.text()).replace(/^\uFEFF/,'');title=file.name.replace(/\.(txt|mml)$/i,'');$('meter-map').value='0 4/4';$('pickup').value='';$('final-partial').value='';$('drum-profile').value='';programs.fill(0);markDirty();toast('已開啟原文；請確認拍號後檢查並載入')}catch(e){toast(e.message)}e.target.value=''});
$('play').addEventListener('click',async()=>{try{if(sourceMode){if(source.paused)await source.play();else source.pause()}else if(player.playing)player.pause();else await player.play();refreshTransport()}catch(e){toast(e.message)}});
$('stop').addEventListener('click',()=>{player.stop();source.pause();sourceMode=false;refreshTransport();drawRoll()});
$('seek').addEventListener('input',async e=>{const pos=Number(e.target.value)/1000*player.duration;try{if(sourceMode){const target=pos+Number($('audio-offset').value||0);if(target<0||target>source.duration)throw Error('原曲沒有此時間位置');source.currentTime=target}else await player.seek(pos);refreshTransport();drawRoll()}catch(e){toast(e.message)}});
$('layer').addEventListener('change',()=>{player.setMix({layer:Number($('layer').value)});drawRoll()});$('master').addEventListener('input',()=>{const volume=Number($('master').value)/100;player.setMix({volume});source.volume=volume});
for(const id of ['loop-start','loop-end','loop-enabled'])$(id).addEventListener('change',()=>{try{player.setLoop(Number($('loop-start').value),Number($('loop-end').value),$('loop-enabled').checked);if(player.playing){const pos=player.position;player.pause();void player.seek(pos).then(()=>player.play()).catch(e=>toast(e.message))}}catch(e){$('loop-enabled').checked=false;player.setLoop(0,0,false);toast(e.message)}});
$('audio-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>250*1024*1024){toast('第一版音檔上限250 MB');return}source.pause();player.pause();sourceMode=false;if(sourceUrl)URL.revokeObjectURL(sourceUrl);sourceFile=file;sourceHash=null;sourceUrl=URL.createObjectURL(file);source.src=sourceUrl;source.volume=Number($('master').value)/100;$('audio-name').textContent=file.name+' · 原曲身份與範圍待確認';$('audio-end').value='';$('switch-audio').disabled=dirty;refreshGates();try{const digest=await sha256(await file.arrayBuffer());if(sourceFile===file)sourceHash=digest}catch{toast('音檔指紋未完成，請重新開啟音檔')}e.target.value=''});
source.addEventListener('loadedmetadata',checkAudioTiming);source.addEventListener('error',()=>{toast('瀏覽器無法解碼此音檔，請改用支援的M4A、MP3或WAV');$('switch-audio').disabled=true});source.addEventListener('play',()=>{if(!sourceMode){player.pause();sourceMode=true}refreshTransport()});source.addEventListener('pause',refreshTransport);source.addEventListener('timeupdate',()=>{if(sourceMode&&player.loop&&!source.paused&&currentSeconds()>=player.loop.end)source.currentTime=player.loop.start+Number($('audio-offset').value||0);refreshTransport()});
$('switch-audio').addEventListener('click',switchAudio);for(const id of ['audio-offset','audio-end'])$(id).addEventListener('input',()=>{source.pause();checkAudioTiming()});
$('export-mml').addEventListener('click',()=>download($('mml').value.trim(),'text/plain;charset=utf-8',filename()+'_CANDIDATE.mml'));
$('export-midi').addEventListener('click',()=>download(midi,'audio/midi',filename()+'_PREVIEW.mid'));
$('export-abc').addEventListener('click',()=>download(abc,'text/plain;charset=utf-8',filename()+'_EXPANDED.abc'));
$('export-report').addEventListener('click',async()=>download(JSON.stringify(await report(),null,2),'application/json',filename()+'_VALIDATION.json'));
$('export-project').addEventListener('click',()=>download(JSON.stringify({schema:'mml-workbench-project',version:1,title,mml:$('mml').value,settings:settings(),audioAlignment:{offset:$('audio-offset').value,end:$('audio-end').value},source:sourceFile?{name:sourceFile.name,sha256:sourceHash}:null},null,2),'application/json',filename()+'_PROJECT.json'));
$('project-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>250000)throw Error('專案檔案過大');const p=JSON.parse(await file.text());if(p.schema!=='mml-workbench-project'||p.version!==1||typeof p.mml!=='string'||!p.settings)throw Error('不支援的專案格式');player.stop();source.pause();title=String(p.title||'匯入專案');$('mml').value=p.mml;$('meter-map').value=String(p.settings.meterText||'0 4/4');$('pickup').value=String(p.settings.pickup||'');$('final-partial').value=String(p.settings.finalPartial||'');$('drum-profile').value=String(p.settings.drumText||'');for(let i=0;i<6;i++)programs[i]=Number(p.settings.programs?.[i]??0);$('audio-offset').value=String(p.audioAlignment?.offset||0);$('audio-end').value=String(p.audioAlignment?.end||'');if(sourceUrl)URL.revokeObjectURL(sourceUrl);source.removeAttribute('src');source.load();sourceFile=null;sourceHash=null;sourceMode=false;$('audio-name').textContent=p.source?'請重新開啟原曲：'+String(p.source.name):'尚未加入原曲音檔';markDirty();await validate();toast('專案已載入；原曲檔案需另行開啟')}catch(e){toast(e.message)}e.target.value=''});
let lastFrame=0;function frame(now){if(now-lastFrame>70){if(player.playing||sourceMode&&!source.paused){refreshTransport();drawRoll()}lastFrame=now}requestAnimationFrame(frame)}requestAnimationFrame(frame);window.addEventListener('resize',drawRoll);window.addEventListener('beforeunload',e=>{if(title!=='內建示範'&&dirty){e.preventDefault();e.returnValue=''}});
void validate();
